window.__OPENSTAX_PHYSICS__[17] = {"schemaVersion":"4.0.0-physics","generatedAt":"2026-11-27T01:44:27.407Z","number":17,"code":"ch17","slug":"diffraction-and-interference","title":"Diffraction and Interference","titleVi":"Nhiễu Xạ & Giao Thoa Ánh Sáng (Diffraction & Interference)","sections":[{"uid":"hsphys.ch17.sec00","moduleId":"m54376","number":"17.0","slug":"introduction","title":"Introduction","isIntroduction":true,"learningObjectives":[],"bilingualGuide":null,"keyEquations":[],"subsections":[{"uid":"hsphys.ch17.sec00.sub01","title":"Chapter Introduction","summaryVi":"Tổng quan mở đầu chương: Nhiễu Xạ & Giao Thoa Ánh Sáng (Diffraction & Interference) — giới thiệu hiện tượng thực tế và các câu hỏi nền tảng trước khi đi vào định luật chi tiết.","paragraphs":["Examine a compact disc under white light, noting the colors observed and their locations on the disc. Using the CD, explore the spectra of a few light sources, such as a candle flame, an incandescent bulb, and fluorescent light. If you have ever looked at the reds, blues, and greens in a sunlit soap bubble and wondered how straw-colored soapy water could produce them, you have hit upon one of the many phenomena that can only be explained by the wave character of light. That and other interesting phenomena, such as the dispersion of white light into a rainbow of colors when passed through a narrow slit, cannot be explained fully by geometric optics. In such cases, light interacts with small objects and exhibits its wave characteristics. The topic of this chapter is the branch of optics that considers the behavior of light when it exhibits wave characteristics."],"figures":[{"sourceId":"fs-id1167067264759","filename":"CNX_HSPhysics_17_00_CDcolors.jpg","relativePath":"media/CNX_HSPhysics_17_00_CDcolors.jpg","alt":"Photograph of a compact disc, showing arcs of rainbow colors produced by diffraction."}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":[],"glossary":[],"assessments":[],"stats":{"learningObjectiveCount":0,"keyEquationCount":0,"subsectionCount":1,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":0,"assessmentCount":0}},{"uid":"hsphys.ch17.sec01","moduleId":"m54369","number":"17.1","slug":"understanding-diffraction-and-interference","title":"Understanding Diffraction and Interference","isIntroduction":false,"learningObjectives":["Explain wave behavior of light, including diffraction and interference, including the role of constructive and destructive interference in Young’s single-slit and double-slit experiments","Perform calculations involving diffraction and interference, in particular the wavelength of light using data from a two-slit interference pattern"],"bilingualGuide":{"notebookSummaryVi":"Nguyên lý Huygens, Nhiễu xạ qua khe hẹp và Thí nghiệm Giao thoa 2 khe Young (d sinθ = mλ cho vân sáng).","wordProblemCues":[{"phraseEn":"double-slit constructive interference","meaningVi":"Điều kiện vân sáng giao thoa khe Young","mathNotation":"d sinθ = mλ"}],"commonTrapsVi":["Trong thí nghiệm khe Young: m = 0 là vân sáng trung tâm, m = 1, 2, 3... là các vân sáng bậc 1, 2, 3."]},"keyEquations":[],"subsections":[{"uid":"hsphys.ch17.sec01.sub01","title":"Diffraction and Interference","summaryVi":"Nguyên lý Huygens, Nhiễu xạ qua khe hẹp và Thí nghiệm Giao thoa 2 khe Young (d sinθ = mλ cho vân sáng). Thuật ngữ trọng tâm trong mục này: diffraction (Hiện tượng nhiễu xạ ánh sáng), Huygens’s principle (Nguyên lý Huygens), wavefront (Mặt sóng).","paragraphs":["We know that visible light is the type of electromagnetic wave to which our eyes responds. As we have seen previously, light obeys the equation","where \\(c = 3.00\\, \\times \\,{10}^{8}\\) m/s is the speed of light in vacuum, f is the frequency of the electromagnetic wave in Hz (or s –1 ), and \\(\\lambda\\) is its wavelength in m. The range of visible wavelengths is approximately 380 to 750 nm. As is true for all waves, light travels in straight lines and acts like a ray when it interacts with objects several times as large as its wavelength. However, when it interacts with smaller objects, it displays its wave characteristics prominently. Interference is the identifying behavior of a wave.","In Figure 17.1, both the ray and wave characteristics of light can be seen. The laser beam emitted by the observatory represents ray behavior, as it travels in a straight line. Passing a pure, one-wavelength beam through vertical slits with a width close to the wavelength of the beam reveals the wave character of light. Here we see the beam spreading out horizontally into a pattern of bright and dark regions that are caused by systematic constructive and destructive interference. As it is characteristic of wave behavior, interference is observed for water waves, sound waves, and light waves.","That interference is a characteristic of energy propagation by waves is demonstrated more convincingly by water waves. Figure 17.1 shows water waves passing through gaps between some rocks. You can easily see that the gaps are similar in width to the wavelength of the waves and that this causes an interference pattern as the waves pass beyond the gaps. A cross-section across the waves in the foreground would show the crests and troughs characteristic of an interference pattern.","Light has wave characteristics in various media as well as in a vacuum. When light goes from a vacuum to some medium, such as water, its speed and wavelength change, but its frequency, f , remains the same. The speed of light in a medium is \\(v = c/n\\), where n is its index of refraction. If you divide both sides of the equation \\(c = f\\lambda\\) by n , you get \\(c/n = v = f\\lambda /n\\) . Therefore, \\(v = f{\\lambda}_{n}\\), where \\({\\lambda}_{n}\\) is the wavelength in a medium, and","where \\(\\lambda\\) is the wavelength in vacuum and n is the medium’s index of refraction. It follows that the wavelength of light is smaller in any medium than it is in vacuum. In water, for example, which has n = 1.333, the range of visible wavelengths is (380 nm)/1.333 to (760 nm)/1.333, or \\({\\lambda}_{n} =\\) 285–570 nm. Although wavelengths change while traveling from one medium to another, colors do not, since colors are associated with frequency.","The Dutch scientist Christiaan Huygens (1629–1695) developed a useful technique for determining in detail how and where waves propagate. He used wavefronts , which are the points on a wave’s surface that share the same, constant phase (such as all the points that make up the crest of a water wave). Huygens’s principle states, “Every point on a wavefront is a source of wavelets that spread out in the forward direction at the same speed as the wave itself. The new wavefront is a line tangent to all of the wavelets.”","Figure 17.1 shows how Huygens’s principle is applied. A wavefront is the long edge that moves; for example, the crest or the trough. Each point on the wavefront emits a semicircular wave that moves at the propagation speed v . These are drawn later at a time, t , so that they have moved a distance \\(s = vt\\) . The new wavefront is a line tangent to the wavelets and is where the wave is located at time t . Huygens’s principle works for all types of waves, including water waves, sound waves, and light waves. It will be useful not only in describing how light waves propagate, but also in how they interfere.","What happens when a wave passes through an opening, such as light shining through an open door into a dark room? For light, you expect to see a sharp shadow of the doorway on the floor of the room, and you expect no light to bend around corners into other parts of the room. When sound passes through a door, you hear it everywhere in the room and, thus, you understand that sound spreads out when passing through such an opening. What is the difference between the behavior of sound waves and light waves in this case? The answer is that the wavelengths that make up the light are very short, so that the light acts like a ray. Sound has wavelengths on the order of the size of the door, and so it bends around corners.","If light passes through smaller openings, often called slits, you can use Huygens’s principle to show that light bends as sound does (see Figure 17.1). The bending of a wave around the edges of an opening or an obstacle is called diffraction . Diffraction is a wave characteristic that occurs for all types of waves. If diffraction is observed for a phenomenon, it is evidence that the phenomenon is produced by waves. Thus, the horizontal diffraction of the laser beam after it passes through slits in Figure 17.1 is evidence that light has the properties of a wave.","Once again, water waves present a familiar example of a wave phenomenon that is easy to observe and understand, as shown in Figure 17.1.","The fact that Huygens’s principle worked was not considered enough evidence to prove that light is a wave. People were also reluctant to accept light’s wave nature because it contradicted the ideas of Isaac Newton, who was still held in high esteem. The acceptance of the wave character of light came after 1801, when the English physicist and physician Thomas Young (1773–1829) did his now-classic double-slit experiment (see Figure 17.1).","When light passes through narrow slits, it is diffracted into semicircular waves, as shown in Figure 17.1 (a). Pure constructive interference occurs where the waves line up crest to crest or trough to trough. Pure destructive interference occurs where they line up crest to trough. The light must fall on a screen and be scattered into our eyes for the pattern to be visible. An analogous pattern for water waves is shown in Figure 17.1 (b). Note that regions of constructive and destructive interference move out from the slits at well-defined angles to the original beam. Those angles depend on wavelength and the distance between the slits, as you will see below.","This simulation demonstrates most of the wave phenomena discussed in this section. First, observe interference between two sources of electromagnetic radiation without adding slits. See how water waves, sound, and light all show interference patterns. Stay with light waves and use only one source. Create diffraction patterns with one slit and then with two. You may have to adjust slit width to see the pattern.","Visually compare the slit width to the wavelength. When do you get the best-defined diffraction pattern?"],"figures":[{"sourceId":"fs-id1167063515329","filename":"CNX_HSPhysics_17_01_RayWave.jpg","relativePath":"media/CNX_HSPhysics_17_01_RayWave.jpg","alt":"(a) Photo of a laser beam directed vertically from an observatory into a night sky. (b) Photo of a horizontal line of about twenty closely spaced red dots. The five dots in the center are much brighter than the others."},{"sourceId":"fs-id1167067176426","filename":"CNX_HSPhysics_17_01_Waterwave.jpg","relativePath":"media/CNX_HSPhysics_17_01_Waterwave.jpg","alt":"Drawing of two groups of rocks on a beach. Waves from the top of figure produce three sets of curved wavefronts that expand outward as they pass through gaps between the rocks."},{"sourceId":"fs-id1167063569990","filename":"CNX_HSPhysics_17_01_Wavefront.jpg","relativePath":"media/CNX_HSPhysics_17_01_Wavefront.jpg","alt":"Drawing with vertical lines labeled “old wavefront” (on the left) and “new wavefront” (on the right). Semicircular wavelets expand to the right from points on the old wavefront. The new wavefront is the tangent to those circles. The two wavefronts are separated by a distance s. A formula states “s is the product of the wave speed v and time t.”"},{"sourceId":"fs-id1167063879901","filename":"CNX_HSPhysics_17_01_Diffractn.jpg","relativePath":"media/CNX_HSPhysics_17_01_Diffractn.jpg","alt":"Three drawings of evenly spaced parallel vertical lines represent straight wavefronts moving to the right and passing through three openings in a barrier. The drawing on the left shows vertical straight lines to the left of a wide opening, overlaid with horizontal arrows pointing to the right, and three parallel lines to the right of the opening. The lines to the right of the opening are roughly the same length as the opening. The upper and lower ends of the lines to the right are swept to the left, forming small curves, but the lines are mostly straight. The small curves at the top are overlaid with an arrow pointing to the right and slightly upward; the small curves at the bottom are overlaid with an arrow pointing to the right and slightly downward. The drawing in the middle shows vertical straight lines to the left of a narrower opening and three parallel lines to the right of the opening. The lines to the right of the opening are roughly the same length as the opening, which is smaller than the opening in the drawing on the left. The upper and lower ends of the lines to the right of the opening are swept to the left, forming small curves, but the lines are mostly straight. The drawing on the right shows vertical straight lines to the left of a very narrow opening, overlaid with one horizontal arrows pointing to the right, and three concentric circular arcs to the right of the opening."},{"sourceId":"fs-id1167066835446","filename":"CNX_HSPhysics_17_01_diffractn2.jpg","relativePath":"media/CNX_HSPhysics_17_01_diffractn2.jpg","alt":"Drawing of ocean waves passing through a narrow gap in a reef. The waves form semicircular wavelets on the beach, which are centered on the gap in the reef."},{"sourceId":"fs-id1167067061559","filename":"CNX_HSPhysics_17_01_2slit.jpg","relativePath":"media/CNX_HSPhysics_17_01_2slit.jpg","alt":"Drawing of a beam of light diffracted by two slits. Two arrows pointing upward and to the right have their points at the vertical slits. A pattern is on a second screen, upward and to the right, consists of about 14 vertical bright bands that are the same height as the slits but have a horizontal spacing closer than the slits."},{"sourceId":"fs-id1167063790669","filename":"CNX_HSPhysics_17_01_2slit2.jpg","relativePath":"media/CNX_HSPhysics_17_01_2slit2.jpg","alt":"(a) Drawing of vertical lines to the left of a screen with two slits, labeled “S-one” and “S-two.” Vertical lines on the left are labeled “Wavefront.” They are overlaid with arrows labeled “Rays.” Two sets of overlapping circular arcs expand outward from the two slits to a screen at the right. The screen on the right is labeled “Screen.” Each set consists of alternating solid and dotted lines. A line from the point on the screen midway between the two slits extends to the center of the screen on the right, toward a label “Max.” Above the Max are other labels on the screen. They are “Min,” “Max,” and another “Min.” Lines run from the screen at the left to those labels at the right. The screen at the right also has a symmetrical arrangement of lines and labels “Min” and “Max” below the central Max. (b) Drawing of semicircles waves moving to the right from two points. (c) A vertical band of closely spaced horizontal red bands. There are about nine bands in the center with a dark space below, four bands that are somewhat dimmer, another dark space, and a still dimmer group of three bands. A symmetrical pattern of red bands and dark spaces and minima appears above the central maximum."}],"tables":[]},{"uid":"hsphys.ch17.sec01.sub02","title":"Calculations Involving Diffraction and Interference","summaryVi":"Nguyên lý Huygens, Nhiễu xạ qua khe hẹp và Thí nghiệm Giao thoa 2 khe Young (d sinθ = mλ cho vân sáng). Thuật ngữ trọng tâm trong mục này: diffraction (Hiện tượng nhiễu xạ ánh sáng), monochromatic (Ánh sáng đơn sắc).","paragraphs":["The fact that the wavelength of light of one color, or monochromatic light, can be calculated from its two-slit diffraction pattern in Young’s experiments supports the conclusion that light has wave properties. To understand the basis of such calculations, consider how two waves travel from the slits to the screen. Each slit is a different distance from a given point on the screen. Thus different numbers of wavelengths fit into each path. Waves start out from the slits in phase (crest to crest), but they will end up out of phase (crest to trough) at the screen if the paths differ in length by half a wavelength, interfering destructively. If the paths differ by a whole wavelength, then the waves arrive in phase (crest to crest) at the screen, interfering constructively. More generally, if the paths taken by the two waves differ by any half-integral number of wavelengths \\((\\frac{1}{2}\\lambda ,\\frac{3}{2}\\lambda ,\\frac{5}{2}\\lambda ,\\text{etc}\\text{.)}\\), then destructive interference occurs. Similarly, if the paths taken by the two waves differ by any integral number of wavelengths \\((\\lambda ,2\\lambda ,3\\lambda ,\\text{etc}\\text{.)}\\), then constructive interference occurs.","Figure 17.1 shows how to determine the path-length difference for waves traveling from two slits to a common point on a screen. If the screen is a large distance away compared with the distance between the slits, then the angle \\(\\theta\\) between the path and a line from the slits perpendicular to the screen (see the figure) is nearly the same for each path. That approximation and simple trigonometry show the length difference, \\(\\Delta L\\), to be \\(dsin\\theta\\), where d is the distance between the slits,","To obtain constructive interference for a double slit, the path-length difference must be an integral multiple of the wavelength, or","Similarly, to obtain destructive interference for a double slit, the path-length difference must be a half-integral multiple of the wavelength, or","The number m is the order of the interference. For example, m = 4 is fourth-order interference.","Figure 17.1 shows how the intensity of the bands of constructive interference decreases with increasing angle.","Light passing through a single slit forms a diffraction pattern somewhat different from that formed by double slits. Figure 17.1 shows a single-slit diffraction pattern. Note that the central maximum is larger than those on either side, and that the intensity decreases rapidly on either side.","The analysis of single-slit diffraction is illustrated in Figure 17.1. Assuming the screen is very far away compared with the size of the slit, rays heading toward a common destination are nearly parallel. That approximation allows a series of trigonometric operations that result in the equations for the minima produced by destructive interference.","or","When rays travel straight ahead, they remain in phase and a central maximum is obtained. However, when rays travel at an angle \\(\\theta\\) relative to the original direction of the beam, each ray travels a different distance to the screen, and they can arrive in or out of phase. Thus, a ray from the center travels a distance \\(\\lambda /2\\) farther than the ray from the top edge of the slit, they arrive out of phase, and they interfere destructively. Similarly, for every ray between the top and the center of the slit, there is a ray between the center and the bottom of the slit that travels a distance \\(\\lambda /2\\) farther to the common point on the screen, and so interferes destructively. Symmetrically, there will be another minimum at the same angle below the direct ray.","Below we summarize the equations needed for the calculations to follow.","The speed of light in a vacuum, c , the wavelength of the light, \\(\\lambda\\), and its frequency, f , are related as follows.","The wavelength of light in a medium, \\({\\lambda}_{n}\\), compared to its wavelength in a vacuum, \\(\\lambda\\), is given by","To calculate the positions of constructive interference for a double slit, the path-length difference must be an integral multiple, m , of the wavelength. \\(\\lambda\\)","where d is the distance between the slits and \\(\\theta\\) is the angle between a line from the slits to the maximum and a line perpendicular to the barrier in which the slits are located. To calculate the positions of destructive interference for a double slit, the path-length difference must be a half-integral multiple of the wavelength:","For a single-slit diffraction pattern, the width of the slit, D , the distance of the first ( m = 1) destructive interference minimum, y , the distance from the slit to the screen, L , and the wavelength, \\(\\lambda\\), are given by","Also, for single-slit diffraction,","where \\(\\theta\\) is the angle between a line from the slit to the minimum and a line perpendicular to the screen, and m is the order of the minimum."],"figures":[{"sourceId":"fs-id1167067153749","filename":"CNX_HSPhysics_17_01_2slit3.jpg","relativePath":"media/CNX_HSPhysics_17_01_2slit3.jpg","alt":"Drawing showing two vertical screens. The screen the left has two slits labeled “S-one” and “S-two.” The screen on the right is labeled “Screen.” Two arrows labeled “L-one” and “L-two” point upward and to the right. They begin at their respective slits and meet at the screen on the right. The distance between slits S-one and S-two is labeled “d,” and that distance is the hypotenuse of a right triangle. The shorter leg of the right triangle is labeled “delta-L.” It extends from the lower slit, S-two, upward and to the right along the arrow leaving slit S-two. The longer leg of the triangle is a line perpendicular to the two light rays and having one end at the upper slit, S-one. The angle of the vertex of the triangle located at slit S-one is labeled “theta.” A formula states  “the distance delta-L as the product of the distance d and the sine of the angle theta.”"},{"sourceId":"fs-id1167067068901","filename":"CNX_HSPhysics_17_01_2slit4.jpg","relativePath":"media/CNX_HSPhysics_17_01_2slit4.jpg","alt":"Two drawings showing diffraction by two slits. The first drawing, on the left shows, two vertical screens. The screen on the left has two slits separated by a vertical distance labeled “d.” A second screen is shown a to the right of the screen with the slits, separated by a horizontal distance labeled “x.” The vertical screen at the right shows a graph of a series of peaks and valleys that grow horizontally to the left. The tallest peak is at the center, with valleys and successively smaller peaks arranged symmetrically above and below it. A horizontal line runs from the point midway between the slits in the screen at the left through the central peak of the graph. A dotted line runs from that midway point through the first peak above the center. A second dotted line runs from the midway point through the second maximum. Those dotted lines make angles labeled “theta-one” and “theta-two” with the horizontal line. The peaks above the center are distances labeled “y-one” and “y-two” above the center. The second drawing, on the right shows, a vertical array of horizontal bright bands on a black background. They are aligned with the peaks of the graph in the first drawing. The bands are all of the same length but are of differing widths. The widest band is in the center and successively narrower bands are arranged symmetrically above and below it."},{"sourceId":"fs-id1167067013970","filename":"CNX_HSPhysics_17_01_1slit.jpg","relativePath":"media/CNX_HSPhysics_17_01_1slit.jpg","alt":"(a) A drawing of a single slit in a vertical screen. The slit has width labeled “D.” (b) Drawing showing two patterns. On the left, a graph has a series of peaks and valleys that grow horizontally to the left. The central peak is largest, with much smaller peaks arranged symmetrically above and below it. To the right of the graph, a second pattern is a vertical array of horizontal bright bands separated by dark bands. They are aligned with the peaks of the graph in the first drawing. The bands are all of the same length but are of differing widths. The widest band is in the center and narrower bands are arranged symmetrically above and below it. (c) A version of the graph of the pattern in drawing (b) rotated so that the peaks grow upward from a horizontal axis. The height of the peaks is labeled “Intensity,” and the central peak is much higher and wider than the other peaks. The horizontal axis is labeled as the “sine of theta,” and the largest, central peak is located at a point on the horizontal axis labeled “zero.” Three valleys are located to the right of the central maximum at distances that are labeled “lambda divided by D,” “two lambda divided by D,” and “three lambda divided by D.” Three other valleys are located to the left of the center at distances that are labeled “negative lambda divided by D,” “negative two lambda divided by D,” and “negative three lambda divided by D.”"},{"sourceId":"fs-id1167067315883","filename":"CNX_HSPhysics_17_01_1slit2.jpg","relativePath":"media/CNX_HSPhysics_17_01_1slit2.jpg","alt":"Drawing entitled “Destructive interference.” It shows two screens, one on the left having a slit with width labeled “D.” The distance from the slit to the screen on the right is labeled “L.” It is represented as a dashed line that runs through the center of the slit and is perpendicular to both screens. A solid line extends upward and to the right from the center of the slit to strike the screen on the right. That line forms an angle labeled “theta” with the horizontal dashed line. A second solid line, from the top of the slit, extends upward and to the right to strike the same point as the first solid line. That point is a distance labeled “y” above the horizontal dashed line. A formula states that “D times the sine of the angle theta is equal to m times the wavelength lambda.” A second formula states that “D times y divided by L is equal to m times lambda.”"}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch17.sec01.ex01","number":"17.1.1","title":"Two-Slit Interference","problem":"Suppose you pass light from a He-Ne laser through two slits separated by 0.0100 mm, and you find that the third bright line on a screen is formed at an angle of 10.95º relative to the incident beam. What is the wavelength of the light?","problemImages":[],"strategy":"The third bright line is due to third-order constructive interference, which means that m = 3. You are given d = 0.0100 mm and \\(\\theta\\) = 10.95º. The wavelength can thus be found using the equation \\(dsin\\theta = m\\lambda\\) for constructive interference.","solution":"The equation is \\(dsin\\theta = m\\lambda\\) . Solving for the wavelength, \\(\\lambda\\), gives\n\\(\\lambda = \\frac{dsin\\theta}{m}\\text{.}\\)\nSubstituting known values yields\n\\(\\lambda = \\frac{(0.0100\\,\\text{mm})(sin10.95°)}{3} = 6.33\\, \\times \\,{10}^{-4}\\text{mm} = 633\\,\\text{nm}\\text{.}\\)","solutionImages":[],"solutionTables":[],"discussion":"To three digits, 633 nm is the wavelength of light emitted by the common He-Ne laser. Not by coincidence, this red color is similar to that emitted by neon lights. More important, however, is the fact that interference patterns can be used to measure wavelength. Young did that for visible wavelengths. His analytical technique is still widely used to measure electromagnetic spectra. For a given order, the angle for constructive interference increases with \\(\\lambda\\), so spectra (measurements of intensity versus wavelength) can be obtained."},{"uid":"hsphys.ch17.sec01.ex02","number":"17.1.2","title":"Single-Slit Diffraction","problem":"Visible light of wavelength 550 nm falls on a single slit and produces its second diffraction minimum at an angle of 45.0° relative to the incident direction of the light. What is the width of the slit?","problemImages":[],"strategy":"From the given information, and assuming the screen is far away from the slit, you can use the equation \\(Dsin\\theta = m\\lambda\\) to find D .","solution":"Quantities given are \\(\\lambda\\) = 550 nm, m = 2, and \\({\\theta}_{2}\\) = 45.0°. Solving the equation \\(Dsin\\theta = m\\lambda\\) for D and substituting known values gives\n\\(D = \\frac{m\\lambda}{\\text{sin}\\theta} = \\frac{2(550\\,\\text{nm})}{\\text{sin}45.0°} = 1.56\\, \\times \\,{10}^{-6}\\text{m.}\\)","solutionImages":[],"solutionTables":[],"discussion":"You see that the slit is narrow (it is only a few times greater than the wavelength of light). That is consistent with the fact that light must interact with an object comparable in size to its wavelength in order to exhibit significant wave effects, such as this single-slit diffraction pattern."}],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":["The wavelength of light varies with the refractive index of the medium.","Slits produce a diffraction pattern if their width and separation are similar to the wavelength of light passing through them.","Interference bands of a single-slit diffraction pattern can be predicted.","Interference bands of a double-slit diffraction pattern can be predicted."],"glossary":[{"term":"diffraction","termVi":"Hiện tượng nhiễu xạ ánh sáng","ipa":"/dɪˈfræk.ʃən/","definition":"bending of a wave around the edges of an opening or an obstacle","definitionVi":"Sự bẻ cong và lan tỏa của sóng ánh sáng khi đi qua khe hẹp hoặc mép vật cản có kích thước cỡ bước sóng.","memoryTipVi":"Khe càng hẹp → ánh sáng nhiễu xạ loe ra càng rộng!"},{"term":"Huygens’s principle","termVi":"Nguyên lý Huygens","ipa":"/ˈhaɪ.ɡənz/","definition":"Every point on a wavefront is a source of wavelets that spread out in the forward direction at the same speed as the wave itself; the new wavefront is a line tangent to all of the wavelets.","definitionVi":"Mỗi điểm trên mặt sóng có thể coi như một nguồn phát sóng cầu thứ cấp mới.","memoryTipVi":"Giải thích trực quan cả phản xạ, khúc xạ lẫn nhiễu xạ."},{"term":"monochromatic","termVi":"Ánh sáng đơn sắc","ipa":"/ˌmɒn.ə.krəˈmæt.ɪk/","definition":"one color","definitionVi":"Ánh sáng chỉ có đúng một bước sóng (một màu duy nhất, như tia laser đỏ).","memoryTipVi":"Mono (một) + Chroma (màu)."},{"term":"wavefront","termVi":"Mặt sóng","ipa":"/ˈweɪv.frʌnt/","definition":"points on a wave surface that all share an identical, constant phase","definitionVi":"Tập hợp tất cả các điểm dao động cùng pha trên sóng (luôn vuông góc với tia sáng).","memoryTipVi":"Tia sáng luôn vuông góc với mặt sóng."}],"assessments":[{"uid":"hsphys.ch17.sec01.q005","sourceId":"fs-id1167067010907","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"What is the width of a single slit through which 610-nm orange light passes to form a first diffraction minimum at an angle of 30.0°?","images":[],"choices":[{"label":"a","text":"0.863 µm"},{"label":"b","text":"0.704 µm"},{"label":"c","text":"0.610 µm"},{"label":"d","text":"1.22 µm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec01.q006","sourceId":"fs-id1167066947419","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Which behavior of light is indicated by an interference pattern?","images":[],"choices":[{"label":"a","text":"ray behavior"},{"label":"b","text":"particle behavior"},{"label":"c","text":"corpuscular behavior"},{"label":"d","text":"wave behavior"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec01.q007","sourceId":"eip-id1166849760723","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Which behavior of light is indicated by diffraction?","images":[],"choices":[{"label":"a","text":"wave behavior"},{"label":"b","text":"particle behavior"},{"label":"c","text":"ray behavior"},{"label":"d","text":"corpuscular behavior"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec01.q010","sourceId":"fs-id1167067010907","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the width of a single slit through which 610-nm orange light passes to form a first diffraction minimum at an angle of 30.0°?","images":[],"choices":[{"label":"a","text":"0.863 µm"},{"label":"b","text":"0.704 µm"},{"label":"c","text":"0.610 µm"},{"label":"d","text":"1.22 µm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec01.q011","sourceId":"fs-id1167061444260","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the distance between two slits that produce a diffraction pattern with the first minimum at an angle of 45.0° when 410-nm violet light passes through the slits?","images":[],"choices":[{"label":"a","text":"2,030 nm"},{"label":"b","text":"1,450 nm"},{"label":"c","text":"410 nm"},{"label":"d","text":"290 nm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec01.q012","sourceId":"fs-id1167067203697","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A breakwater at the entrance to a harbor consists of a rock barrier with a 50.0 - m -wide opening. Ocean waves with a 20.0-m wavelength approach the opening straight on. At what angle to the incident direction are the boats inside the harbor most protected against wave action?","images":[],"choices":[{"label":"a","text":"11.5°"},{"label":"b","text":"7.46°"},{"label":"c","text":"5.74°"},{"label":"d","text":"23.6°"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec01.q013","sourceId":"fs-id1167067202897","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which remains unchanged when a monochromatic beam of light passes from air into water?","images":[],"choices":[{"label":"a","text":"the speed of the light"},{"label":"b","text":"the direction of the beam"},{"label":"c","text":"the frequency of the light"},{"label":"d","text":"the wavelength of the light"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec01.q014","sourceId":"fs-id1167067152803","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Two slits are separated by a distance of 3500 nm . If light with a wavelength of 500 nm passes through the slits and produces an interference pattern, the m = ________ order minimum appears at an angle of 30.0°.","images":[],"choices":[{"label":"a","text":"0"},{"label":"b","text":"1"},{"label":"c","text":"2"},{"label":"d","text":"3"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec01.q015","sourceId":"eip-id1166850252492","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"In the sunlight, the shadow of a building has fuzzy edges even if the building does not. Is this a refraction effect? Explain.","images":[],"choices":[{"label":"a","text":"Yes, this is a refraction effect, where every point on the building acts as the origin for a new wavefront."},{"label":"b","text":"Yes, this is a refraction effect, where the whole building acts as the origin for a new wavefront."},{"label":"c","text":"No, this is a diffraction effect, where every point on the edge of the buildings shadow acts as the origin for a new wavefront."},{"label":"d","text":"No, this is a diffraction effect, where the whole building acts as the origin for a new wavefront."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec01.q019","sourceId":"fs-id1167063556871","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What is the longest wavelength of light passing through a single slit of width 1.20 μm for which there is a first-order minimum?","images":[],"choices":[{"label":"a","text":"1.04 µm"},{"label":"b","text":"0.849 µm"},{"label":"c","text":"0.600 µm"},{"label":"d","text":"2.40 µm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec01.q021","sourceId":"fs-id1167063892006","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"A double slit is located at a distance x from a screen, with the distance along the screen from the center given by y . When the distance d between the slits is relatively large, there will be numerous bright bands.\nFor small angles (where sin θ = θ , with θ in radians), what is the distance between fringes?","images":[],"choices":[{"label":"a","text":"\\(\\Delta y = \\frac{d}{x\\lambda}\\)"},{"label":"b","text":"\\(\\Delta y = \\frac{xd}{\\lambda}\\)"},{"label":"c","text":"\\(\\Delta y = \\frac{\\lambda}{xd}\\)"},{"label":"d","text":"\\(\\Delta y = \\frac{x\\lambda}{d}\\)"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":0,"subsectionCount":2,"workedExampleCount":2,"snapLabCount":0,"glossaryCount":4,"assessmentCount":11}},{"uid":"hsphys.ch17.sec02","moduleId":"m54371","number":"17.2","slug":"applications-of-diffraction-interference-and-coherence","title":"Applications of Diffraction, Interference, and Coherence","isIntroduction":false,"learningObjectives":["Explain behaviors of waves, including reflection, refraction, diffraction, interference, and coherence, and describe applications based on these behaviors","Perform calculations related to applications based on wave properties of light"],"bilingualGuide":{"notebookSummaryVi":"Cách tử nhiễu xạ (Diffraction Grating), Giao thoa bản mỏng (bong bóng xà phòng), Tia Laser và Tiêu chuẩn phân giải Rayleigh (θ = 1.22λ/D).","wordProblemCues":[{"phraseEn":"Rayleigh criterion","meaningVi":"Giới hạn góc phân giải của kính thiên văn/mắt","mathNotation":"θ = 1.22λ / D"}],"commonTrapsVi":["Bước sóng λ càng NGẮN (hoặc khẩu độ D càng LỚN) thì góc giới hạn θ càng nhỏ → nhìn chi tiết càng sắc nét!"]},"keyEquations":[{"name":"wavelength change with change in medium","formula":"\\({\\lambda}_{n} = \\frac{\\lambda}{n}\\)"},{"name":"diffraction grating constructive interference","formula":"\\(dsin\\theta = m\\lambda\\)"},{"name":"resolution","formula":"\\(\\theta = 1.22\\frac{\\lambda}{D}\\)"}],"subsections":[{"uid":"hsphys.ch17.sec02.sub01","title":"Wave-Based Applications of Light","summaryVi":"Cách tử nhiễu xạ (Diffraction Grating), Giao thoa bản mỏng (bong bóng xà phòng), Tia Laser và Tiêu chuẩn phân giải Rayleigh (θ = 1.22λ/D). Thuật ngữ trọng tâm trong mục này: diffraction grating (Cách tử nhiễu xạ), iridescence (Hiện tượng ánh ngũ sắc (Giao thoa bản mỏng)), laser (Tia Laser), monochromator (Bộ đơn sắc hóa ánh sáng).","paragraphs":["In 1917, Albert Einstein was thinking about photons and excited atoms. He considered an atom excited by a certain amount of energy and what would happen if that atom were hit by a photon with the same amount of energy. He suggested that the atom would emit a photon with that amount of energy, and it would be accompanied by the original photon. The exciting part is that you would have two photons with the same energy and they would be in phase. Those photons could go on to hit other excited atoms, and soon you would have a stream of in-phase photons. Such a light stream is said to be coherent . Some four decades later, Einstein’s idea found application in a process called, light amplification by stimulated emission of radiation . Take the first letters of all the words (except by and “of”) and write them in order. You get the word laser (see Figure 17.1 (a)), which is the name of the device that produces such a beam of light.","Laser beams are directional, very intense, and narrow (only about 0.5 mm in diameter). These properties lead to a number of applications in industry and medicine. The following are just a few examples:","This animation allows you to examine the workings of a laser. First view the picture of a real laser. Change the energy of the incoming photons, and see if you can match it to an excitation level that will produce pairs of coherent photons. Change the excitation level and try to match it to the incoming photon energy.","In the animation there is only one excited atom. Is that the case for a real laser? Explain.","An interesting thing happens if you pass light through a large number of evenly-spaced parallel slits. Such an arrangement of slits is called a diffraction grating . An interference pattern is created that is very similar to the one formed by double-slit diffraction (see Figure 17.1 and Figure 17.1). A diffraction grating can be manufactured by scratching glass with a sharp tool to form a number of precisely positioned parallel lines, which act like slits. Diffraction gratings work both for transmission of light, as in Figure 17.2, and for reflection of light, as on the butterfly wings or the Australian opal shown in Figure 17.2, or the CD pictured in the opening illustration of this chapter. In addition to their use as novelty items, diffraction gratings are commonly used for spectroscopic dispersion and analysis of light. What makes them particularly useful is the fact that they form a sharper pattern than do double slits. That is, their bright regions are narrower and brighter, while their dark regions are darker. Figure 17.2 shows idealized graphs demonstrating the sharper pattern. Natural diffraction gratings occur in the feathers of certain birds. Tiny, fingerlike structures in regular patterns act as reflection gratings, producing constructive interference that gives the feathers colors not solely due to their pigmentation. The effect is called iridescence .","Can you see the grooves on a CD or DVD (see Figure 17.2)? You may think you can because you know they are there, but they are extremely narrow—1,600 in a millimeter. Because the width of the grooves is similar to wavelengths of visible light, they form a diffraction grating. That is why you see rainbows on a CD. The colors are attractive, but they are incidental to the functions of storing and retrieving audio and other data.","The grooves are actually one continuous groove that spirals outward from the center. Data are recorded in the grooves as binary code (zeroes and ones) in small pits. Information in the pits is detected by a laser that tracks along the groove. It gets even more complicated: The speed of rotation must be varied as the laser tracks toward the circumference so that the linear speed along the groove remains constant. There is also an error correction mechanism to prevent the laser beam from getting off track. A diffraction grating is used to create the first two maxima on either side of the track. If those maxima are not the same distance from the track, an error is indicated and then corrected.","The pits are reflective because they have been coated with a thin layer of aluminum. That allows the laser beam to be reflected back and directed toward a photodiode detector. The signal can then be processed and converted to the audio we hear.","The longest wavelength of visible light is about 780 nm . How does that compare to the distance between CD grooves?","Where are diffraction gratings used? Diffraction gratings are key components of monochromators —devices that separate the various wavelengths of incoming light and allow a beam with only a specific wavelength to pass through. Monochromators are used, for example, in optical imaging of particular wavelengths from biological or medical samples. A diffraction grating can be chosen to specifically analyze a wavelength of light emitted by molecules in diseased cells in a biopsy sample, or to help excite strategic molecules in the sample with a selected frequency of light. Another important use is in optical fiber technologies where fibers are designed to provide optimum performance at specific wavelengths. A range of diffraction gratings is available for selecting specific wavelengths for such use.","Diffraction gratings are used in spectroscopes to separate a light source into its component wavelengths. When a material is heated to incandescence, it gives off wavelengths of light characteristic of the chemical makeup of the material. A pure substance will produce a spectrum that is unique, thus allowing identification of the substance. Spectroscopes are also used to measure wavelengths both shorter and longer than visible light. Such instruments have become especially useful to astronomers and chemists. Figure 17.2 shows a diagram of a spectroscope.","Light diffracts as it moves through space, bending around obstacles and interfering constructively and destructively. While diffraction allows light to be used as a spectroscopic tool, it also limits the detail we can obtain in images.","Figure 17.2 (a) shows the effect of passing light through a small circular aperture. Instead of a bright spot with sharp edges, a spot with a fuzzy edge surrounded by circles of light is obtained. This pattern is caused by diffraction similar to that produced by a single slit. Light from different parts of the circular aperture interferes constructively and destructively. The effect is most noticeable when the aperture is small, but the effect is there for large apertures, too.","How does diffraction affect the detail that can be observed when light passes through an aperture? Figure 17.2 (b) shows the diffraction pattern produced by two point light sources that are close to one another. The pattern is similar to that for a single point source, and it is just barely possible to tell that there are two light sources rather than one. If they are closer together, as in Figure 17.2 (c), you cannot distinguish them, thus limiting the detail, or resolution , you can obtain. That limit is an inescapable consequence of the wave nature of light.","There are many situations in which diffraction limits the resolution. The acuity of vision is limited because light passes through the pupil, the circular aperture of the eye. Be aware that the diffraction-like spreading of light is due to the limited diameter of a light beam, not the interaction with an aperture. Thus light passing through a lens with a diameter of D shows the diffraction effect and spreads, blurring the image, just as light passing through an aperture of diameter D does. Diffraction limits the resolution of any system having a lens or mirror. Telescopes are also limited by diffraction, because of the finite diameter, D , of their primary mirror."],"figures":[{"sourceId":"fs-id1167065875050","filename":"CNX_HSPhysics_17_02_Grating.jpg","relativePath":"media/CNX_HSPhysics_17_02_Grating.jpg","alt":"(a) Drawing of a vertical screen with five equally spaced horizontal slits that take up the middle third. A single blue arrow to the left of the barrier point to the right. Five blue arrows from the five slits point to the right, to five small diagrams arranged vertically. (b) Five small diagrams arranged vertically. The middle diagram is a white rectangle. It is labeled “Central white.” Above it is a square with colored bands; from the top, they are red, yellow, green, blue, and purple. The square is labeled “First-order rainbow.” Above the first rainbow is another small square, with the same colors as the one below, but fainter. It is labeled “Second-order rainbow.” Below the central white square is another square with colored bands. They are purple, blue, green, yellow, and red (the opposite order from the upper rainbows), and the square is labeled “First-order rainbow.” The lowest of the five diagrams is a fainter version of the square above it. It is labeled “Second-order rainbow.”"},{"sourceId":"fs-id1167066083117","filename":"CNX_HSPhysics_17_02_Grating2.jpg","relativePath":"media/CNX_HSPhysics_17_02_Grating2.jpg","alt":"(a) Photograph of an opal, with a rounded triangular shape. Most of the upper portion of the triangle is red and yellow. The lower portion is blue, green, and purple. (b) Photograph of a butterfly on a leaf. The wings are blue with white spots at the points of the wings and black bands at the rear edges of the wings."},{"sourceId":"fs-id1167066012716","filename":"CNX_HSPhysics_17_02_Grating3.jpg","relativePath":"media/CNX_HSPhysics_17_02_Grating3.jpg","alt":"(a) Graph labeled “double slit.” A sine curve with three peaks is plotted with its troughs on a horizontal axis. Three points on the axis are labeled, corresponding to three maxima. Left to right, the points are labeled “m equals 1,” m equals zero,” and “m equals 1.” (b) Graph labeled “grating.” A curve with three tall narrow peaks is plotted with its troughs on a horizontal axis. On either side of the three peaks are two much smaller peaks (the larger peaks are separated by a total of four smaller peaks). Three points on the axis are labeled, corresponding to three maxima. Left to right, the points are labeled “m equals 1,” m equals zero,” and “m equals 1.”"},{"sourceId":"fs-id1167064820391","filename":"CNX_HSPhysics_17_02_CD.jpg","relativePath":"media/CNX_HSPhysics_17_02_CD.jpg","alt":"Drawing of a portable CD player. Its cover is open, showing a CD that has a red sector on the lower left, of about 90 degrees, a blue sector on the upper right of about 120 degrees, and a yellow sector between them of about 30 degrees."},{"sourceId":"fs-id1167064708545","filename":"CNX_HSPhysics_17_02_Spectroscp.jpg","relativePath":"media/CNX_HSPhysics_17_02_Spectroscp.jpg","alt":"Drawing of a spectroscope. Drawing shows a flame, two mirrors, grating and detector. A yellow flame at the upper left is labeled “source.” A horizontal arrow from the source extends to a small circular arc, which is concave to the left and slightly downward. The arc is one of two that are labeled “mirrors.” A second arrow extends to the left and downward from the point where the first arrow strikes the mirror, and in turn strikes a rectangular object that is tilted from vertical slightly to the left. The object is labeled “grating.” From the point where the second arrow strikes the grating, a number of colored arrows fan out downward and to the right, forming a narrow triangle. Those arrows in turn strike the second circular arc, labeled as one of the “mirrors,” which is concave to the left and slightly upward. From the second mirror, five colored arrows fan out to the left and slightly downward to form a wider triangle, and they strike a vertical surface labeled “detector.” The purple arrow strikes the top of the detector and the blue arrow slightly below it. The green arrow strikes the middle of the detector, the yellow arrow slightly lower, and the red arrow the bottom of the detector."},{"sourceId":"fs-id1167064766429","filename":"CNX_HSPhysics_17_02_Resolution.jpg","relativePath":"media/CNX_HSPhysics_17_02_Resolution.jpg","alt":"(a) A white circle on a black background is surrounded by a ring that fades outward from gray to black. (b) Two circles, one on the left and one on the right, are surrounded by gray rings. Their circumferences touch, but the circles are distinguishable. (c)Two circles, with surrounding gray rings, have moved closer together and now are indistinguishable. They form a horizontal oval."}],"tables":[]},{"uid":"hsphys.ch17.sec02.sub02","title":"Calculations Involving Diffraction Gratings and Resolution","summaryVi":"Cách tử nhiễu xạ (Diffraction Grating), Giao thoa bản mỏng (bong bóng xà phòng), Tia Laser và Tiêu chuẩn phân giải Rayleigh (θ = 1.22λ/D). Thuật ngữ trọng tâm trong mục này: diffraction grating (Cách tử nhiễu xạ), laser (Tia Laser), Rayleigh criterion (Tiêu chuẩn Rayleigh (Giới hạn phân giải)), resolution (Độ phân giải quang học).","paragraphs":["Early in the chapter, it was mentioned that when light passes from one medium to another, its speed and wavelength change, but its frequency remains constant. The equation","shows how to the wavelength in a given medium, \\({\\lambda}_{n}\\), is related to the wavelength in a vacuum, \\(\\lambda\\), and the refractive index, n , of the medium. The equation is useful for calculating the change in wavelength of a monochromatic laser beam in various media. The analysis of a diffraction grating is very similar to that for a double slit. As you know from the discussion of double slits in Young’s double-slit experiment, light is diffracted by, and spreads out after passing through, each slit. Rays travel at an angle \\(\\theta\\) relative to the incident direction. Each ray travels a different distance to a common point on a screen far away. The rays start in phase, and they can be in or out of phase when they reach a screen, depending on the difference in the path lengths traveled. Each ray travels a distance that differs by \\(dsin\\theta\\) from that of its neighbor, where d is the distance between slits. If \\(dsin\\theta\\) equals an integral number of wavelengths, the rays all arrive in phase, and constructive interference (a maximum) is obtained. Thus, the condition necessary to obtain constructive interference for a diffraction grating is","where d is the distance between slits in the grating, \\(\\lambda\\) is the wavelength of the light, and m is the order of the maximum. Note that this is exactly the same equation as for two slits separated by d . However, the slits are usually closer in diffraction gratings than in double slits, producing fewer maxima at larger angles.","Just what is the resolution limit of an aperture or lens? To answer that question, consider the diffraction pattern for a circular aperture, which, similar to the diffraction pattern of light passing through a slit, has a central maximum that is wider and brighter than the maxima surrounding it (see Figure 17.2 (a)). It can be shown that, for a circular aperture of diameter D , the first minimum in the diffraction pattern occurs at \\(\\theta = 1.22\\lambda /D\\), provided that the aperture is large compared with the wavelength of light, which is the case for most optical instruments. The accepted criterion for determining the diffraction limit to resolution based on diffraction was developed by Lord Rayleigh in the 19th century. The Rayleigh criterion for the diffraction limit to resolution states that two images are just resolvable when the center of the diffraction pattern of one is directly over the first minimum of the diffraction pattern of the other. See Figure 17.2 (b). The first minimum is at an angle of \\(\\theta = 1.22\\lambda /D\\), so that two point objects are just resolvable if they are separated by the angle","where \\(\\lambda\\) is the wavelength of the light (or other electromagnetic radiation) and D is the diameter of the aperture, lens, mirror, etc., with which the two objects are observed. In the expression above, \\(\\theta\\) has units of radians."],"figures":[{"sourceId":"fs-id1167064867809","filename":"CNX_HSPhysics_17_02_Resolutn2.jpg","relativePath":"media/CNX_HSPhysics_17_02_Resolutn2.jpg","alt":"(a) A graph with five peaks. The valleys are on a horizontal axis. The central peak is largest, and it is labeled “intensity.” Four much smaller peaks are arranged symmetrically, two to the left and two to the right. An arrow below the horizontal axis points to the right and is labeled “theta.” Three points are labeled on the horizontal axis, “zero” for the central peak, “negative 1.22 lamda divided by D” for the valley on its left, and “1.22 lamda divided by D” for the valley on its right. (b) A drawing shows two lightbulbs at the bottom. One is labeled “Object 1,” and it is to the right and slightly above the other, labeled “Object 2.” In the middle of the drawing is a vertical screen with a circular hole in it. At the top of the drawing is a vertical screen with two wide peaks graphed on it, which are labeled “Intensities.” A line from Object 1 extends through the hole in the screen and strikes the horizontal axis of the graph directly below the left peak on the graph. Another line from Object two extends through the hole in the screen and strikes the horizontal axis of the graph directly below the right peak on the graph. The angle formed when the two lines cross (where they pass through the hole in the middle screen) is labeled “theta min.”"}],"tables":[]},{"uid":"hsphys.ch17.sec02.sub03","title":"Performance Task","summaryVi":"Cách tử nhiễu xạ (Diffraction Grating), Giao thoa bản mỏng (bong bóng xà phòng), Tia Laser và Tiêu chuẩn phân giải Rayleigh (θ = 1.22λ/D). Thuật ngữ trọng tâm trong mục này: laser (Tia Laser).","paragraphs":["In this performance task you will create one- and two-slit diffraction and observe the interference patterns that result.","NOTE—In your calculations, use 580 nm for \\(\\lambda\\) if you used white light. If you used a colored laser pointer, look up the wavelength of the color. You may find it easier to calculate \\(\\theta\\) from its tangent rather than from its sine.\nWhich experiment gave the most distinct pattern—one or two slits?\nWhat was the width of the single slit? Compare the calculated distance with the measured distance.\nWhat was the distance between the two slits? Compare the calculated distance with the measured distance."],"figures":[],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch17.sec02.ex01","number":"17.2.1","title":"Change of Wavelength","problem":"A monochromatic laser beam of green light with a wavelength of 550 nm passes from air to water. The refractive index of water is 1.33. What will be the wavelength of the light after it enters the water?","problemImages":[],"strategy":"You can assume that the refractive index of air is the same as that of light in a vacuum because they are so close. You then have all the information you need to solve for \\({\\lambda}_{n}\\) .","solution":"\\({\\lambda}_{n} = \\frac{\\lambda}{n} = \\frac{550\\,\\text{nm}}{1.33} = 414\\,\\text{nm}\\)","solutionImages":[],"solutionTables":[],"discussion":"The refractive index of air is 1.0003, so the approximation holds for three significant figures. You would not see the light change color, however. Color is determined by frequency, not wavelength."},{"uid":"hsphys.ch17.sec02.ex02","number":"17.2.2","title":"Diffraction Grating","problem":"A diffraction grating has 2000 lines per centimeter. At what angle will the first-order maximum form for green light with a wavelength of 520 nm?","problemImages":[],"strategy":"You are given enough information to calculate d , and you are given the values of \\(\\lambda\\) and m . You will have to find the arcsin of a number to find \\(\\theta\\) .","solution":"First find d .\n\\(d = \\frac{1\\,\\text{cm}}{2,000} = 5.00\\, \\times \\,{10}^{- 4}\\text{cm = 5,000 nm}\\)\nRearrange the equation for constructive interference conditions for a diffraction grating, and substitute the known values.\n\\(\\begin{aligned} dsin\\theta = m\\lambda \\\\ \\theta = {\\text{sin}}^{- 1}\\frac{m\\lambda}{d} \\\\ = {\\text{sin}}^{- 1}(\\frac{(1)(520)}{5,000}) \\\\ = 5.97 \\end{aligned}\\)","solutionImages":[],"solutionTables":[],"discussion":"This angle seems reasonable for the first maximum. Recall that the meaning of sin ‒1 (or arcsin) is the angle with a sine that is (the unknown) . Remember that the value of \\(sin\\theta\\) will not be greater than 1 for any value of \\(\\theta\\) ."},{"uid":"hsphys.ch17.sec02.ex03","number":"17.2.3","title":"Resolution","problem":"What is the minimum angular spread of a 633-nm-wavelength He-Ne laser beam that is originally 1.00 mm in diameter?","problemImages":[],"strategy":"The diameter of the beam is the same as if it were coming through an aperture of that size, so D = 1.00 mm. You are given \\(\\lambda\\), and you must solve for \\(\\theta\\) .","solution":"\\(\\theta = \\frac{(1.22)\\lambda}{D} = \\frac{(1.22)(633\\,\\text{nm})}{1.00\\, \\times \\,{10}^{6}\\text{nm}} = 7.72 \\times {10}^{-4}\\text{rad} = 0.0442°\\)","solutionImages":[],"solutionTables":[],"discussion":"The conversion factor for radians to degrees is 1.000 radian = 57.3°. The spread is very small and would not be noticeable over short distances. The angle represents the angular separation of the central maximum and the first minimum."}],"snapLabs":[{"uid":"hsphys.ch17.sec02.lab01","title":"Diffraction Grating","text":"A CD (compact disc) or DVD\nA measuring tape\nSunlight near a white wall\nInstructions\nProcedure\nHold the CD in direct sunlight near the wall, and move it around until a circular rainbow pattern appears on the wall.\nMeasure the distance from the CD to the wall and the distance from the center of the circular pattern to a color in the rainbow. Use those two distances to calculate \\(tan\\theta\\) . Find \\(\\text{sin}\\theta\\) .\nLook up the wavelength of the color you chose. That is \\(\\lambda\\) .\nSolve \\(dsin\\theta = m\\lambda\\) for d .\nCompare your answer to the usual spacing between CD tracks, which is 1,600 nm (1.6 μm).\nHow do you know what number to use for m ?\nCount the rainbow rings preceding the chosen color.\nCalculate mfrom the frequency of the light of the chosen color.\nCalculate m from the wavelength of the light of the chosen color.\nThe value of m is fixed for every color.","images":[]},{"uid":"hsphys.ch17.sec02.lab02","title":"Resolution","text":"A sheet of white paper\nA black pen or pencil\nA measuring tape\nInstructions\nProcedure\nDraw two lines several mm apart on a white sheet of paper.\nMove away from the sheet as it is held upright, and measure the distance at which you can just distinguish (resolve) the lines as separate.\nUse \\(\\theta = 1.22\\frac{\\lambda}{D}\\) to calculate D the diameter of your pupil. Use the distance between the lines and the maximum distance at which they were resolved to calculate \\(\\theta\\) . Use the average wavelength for visible light as the value for \\(\\lambda\\) .\nCompare your answer to the average pupil diameter of 3 mm.","images":[]}],"tipsAndFeatures":[{"uid":"hsphys.ch17.sec02.feat01","type":"physics-in-action","title":"Biology: DIC Microscopy","text":"If you were completely transparent, it would be hard to recognize you from your photograph. The same problem arises when using a traditional microscope to view or photograph small transparent objects such as cells and microbes. Microscopes using differential interference contrast (DIC) solve the problem by making it possible to view microscopic objects with enhanced contrast, as shown in Figure 17.2.\nThis aquatic organism was photographed with a DIC microscope. (credit: Public Library of Science)\nA DIC microscope separates a polarized light source into two beams polarized at right angles to each other and coherent with each other, that is, in phase. After passing through the sample, the beams are recombined and realigned so they have the same plane of polarization. They then create an interference pattern caused by the differences in their optical path and the refractive indices of the parts of the sample they passed through. The result is an image with contrast and shadowing that could not be observed with traditional optics.","images":[{"sourceId":"fs-id1167065812528","filename":"CNX_HSPhysics_17_02_DIC.jpg","relativePath":"media/CNX_HSPhysics_17_02_DIC.jpg","alt":"Photo of freshwater alga. A flat green object with a rough texture is divided into forking branches. The largest resembles the letter Y with a very thick stem, tipped to the left so the stem is horizontal. Both arms of the Y fork into two very small branches. Joined to the base of the stem of the Y are other pairs of branches that resemble the letter V, one above and one below, and both angled slightly to the left. Each arm of the V splits into two branches, and then again into very small branches. A mirror image of the Y and two V’s is to the right and the two Y stems are joined."}]}],"summaryPoints":["The focused, coherent radiation emitted by lasers has many uses in medicine and industry.","Characteristics of diffraction patterns produced with diffraction gratings can be determined.","Diffraction gratings have been incorporated in many instruments, including microscopes and spectrometers.","Resolution has a limit that can be predicted."],"glossary":[{"term":"diffraction grating","termVi":"Cách tử nhiễu xạ","ipa":"/ˈɡreɪ.tɪŋ/","definition":"many of evenly spaced slits having dimensions such that they produce an interference pattern","definitionVi":"Tấm quang học chứa hàng nghìn khe hẹp song song cách đều nhau, tách phổ ánh sáng cực sắc nét (d sinθ = mλ).","memoryTipVi":"Mặt dưới đĩa CD/DVD đóng vai trò như một cách tử nhiễu xạ phản xạ!"},{"term":"differential interference contrast (DIC)","termVi":"Kính hiển vi tương phản giao thoa vi sai (DIC)","ipa":"/ˌdɪf.əˈren.ʃəl/","definition":"separating a polarized light source into two beams polarized at right angles to each other and coherent with each other then, after passing through the sample, recombining and realigning the beams so they have the same plane of polarization, and then creating an interference pattern caused by the differences in their optical path and the refractive indices of the parts of the sample they passed through; the result is an image with contrast and shadowing that could not be observed with traditional optics","definitionVi":"Kỹ thuật hiển vi dùng giao thoa ánh sáng để quan sát mẫu sinh học trong suốt rõ nét như ảnh 3D.","memoryTipVi":"Ứng dụng quan trọng trong sinh học tế bào."},{"term":"iridescence","termVi":"Hiện tượng ánh ngũ sắc (Giao thoa bản mỏng)","ipa":"/ˌɪr.ɪˈdes.əns/","definition":"the effect that occurs when tiny, fingerlike structures in regular patterns act as reflection gratings, producing constructive interference that gives feathers colors not solely due to their pigmentation","definitionVi":"Màu sắc thay đổi theo góc nhìn trên bong bóng xà phòng, váng dầu hay cánh bướm do giao thoa ánh sáng.","memoryTipVi":"Không phải do sắc tố mà do cấu trúc giao thoa ánh sáng!"},{"term":"laser","termVi":"Tia Laser","ipa":"/ˈleɪ.zər/","definition":"acronym for a device that produces light amplification by stimulated emission of radiation","definitionVi":"Nguồn phát ánh sáng đơn sắc, định hướng cực cao và kết hợp (cùng pha) cực mạnh.","memoryTipVi":"Viết tắt của Light Amplification by Stimulated Emission of Radiation."},{"term":"monochromator","termVi":"Bộ đơn sắc hóa ánh sáng","ipa":"/ˌmɒn.əˈkrəʊ.mə.tər/","definition":"device that separates the various wavelengths of incoming light and allows a beam with only a specific wavelength to pass through","definitionVi":"Thiết bị quang học lọc ra đúng một bước sóng ánh sáng mong muốn từ chùm sáng phức tạp.","memoryTipVi":"Dùng trong máy quang phổ phân tích hóa học."},{"term":"Rayleigh criterion","termVi":"Tiêu chuẩn Rayleigh (Giới hạn phân giải)","ipa":"/ˈreɪ.li kraɪˈtɪə.ri.ən/","definition":"two images are just resolvable when the center of the diffraction pattern of one is directly over the first minimum of the diffraction pattern of the other","definitionVi":"Giới hạn góc nhỏ nhất để phân biệt rõ hai điểm sáng sát nhau qua ống kính/kính thiên văn: θ = 1.22 λ / D.","memoryTipVi":"Đường kính ống kính D càng lớn → độ phân giải càng cao!"},{"term":"resolution","termVi":"Độ phân giải quang học","ipa":"/ˌrez.əˈluː.ʃən/","definition":"degree to which two images can be distinguished from one another, which is limited by diffraction","definitionVi":"Khả năng phân biệt rõ hai vật thể nằm rất gần nhau thành hai ảnh tách biệt.","memoryTipVi":"Bị giới hạn bởi hiện tượng nhiễu xạ ánh sáng."}],"assessments":[{"uid":"hsphys.ch17.sec02.q005","sourceId":"fs-id1167062541067","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"A beam of yellow light has a wavelength of 600 nm in a vacuum and a wavelength of 397 nm in Plexiglas. What is the refractive index of Plexiglas?","images":[],"choices":[{"label":"a","text":"1.51"},{"label":"b","text":"2.61"},{"label":"c","text":"3.02"},{"label":"d","text":"3.77"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec02.q006","sourceId":"fs-id1167065871199","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"What is the angle between two just-resolved points of light for a 3.00 mm diameter pupil, assuming an average wavelength of 550 nm?","images":[],"choices":[{"label":"a","text":"224 rad"},{"label":"b","text":"183 rad"},{"label":"c","text":"1.83 × 10 –4 rad"},{"label":"d","text":"2.24 × 10 –4 rad"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec02.q007","sourceId":"fs-id1167065946888","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":false,"prompt":"There is a principle related to resolution that is expressed by this equation.\n\\(\\theta = \\frac{\\lambda}{D}\\)\nWhat is that principle stated in full?","images":[],"choices":[],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec02.q008","sourceId":"eip-id1166851082725","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"A principle related to resolution states, “Two images are just resolved when the center of the diffraction pattern of one is directly over the first minimum of the diffraction pattern of the other.” Write the equation that expresses that principle.","images":[],"choices":[{"label":"a","text":"\\(\\theta = 1.22\\frac{D}{\\lambda}\\)"},{"label":"b","text":"\\(\\theta = \\frac{D}{\\lambda}\\)"},{"label":"c","text":"\\(\\theta = \\frac{\\lambda}{D}\\)"},{"label":"d","text":"\\(\\theta = 1.22\\frac{\\lambda}{D}\\)"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec02.q009","sourceId":"eip-id1166851367430","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Which statement completes this resolution?\nTwo images are just resolved when —","images":[],"choices":[{"label":"a","text":"The center of the diffraction pattern of one image is directly over the central maximum of the diffraction pattern of the other."},{"label":"b","text":"The center of the diffraction pattern of one image is directly over the central minimum of the diffraction pattern of the other"},{"label":"c","text":"The center of the diffraction pattern of one image is directly over the first minimum of the diffraction pattern of the other"},{"label":"d","text":"The center of the diffraction pattern of one is directly over the first maximum of the diffraction pattern of the other"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec02.q010","sourceId":"fs-id1167062312031","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"For what type of electromagnetic radiation would a grating with spacing greater than 800 nm be useful as a spectroscopic tool?","images":[],"choices":[{"label":"a","text":"It can be used to analyze spectra only in the infrared portion of the spectrum."},{"label":"b","text":"It can be used to analyze spectra in the entire visible portion of the electromagnetic\nspectrum."},{"label":"c","text":"It can only be used to analyze spectra in the short‐wavelength visible."},{"label":"d","text":"It can only be used to analyze spectra in the short‐wavelength visible and ultraviolet."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec02.q012","sourceId":"fs-id1167062541067","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A beam of yellow light has a wavelength of 600 nm in a vacuum and a wavelength of 397 nm in Plexiglas. What is the refractive index of Plexiglas?","images":[],"choices":[{"label":"a","text":"1.51"},{"label":"b","text":"2.61"},{"label":"c","text":"3.02"},{"label":"d","text":"3.77"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec02.q013","sourceId":"fs-id1167065871199","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"What is the angle between two just-resolved points of light for a 3.00 mm diameter pupil, assuming an average wavelength of 550 nm?","images":[],"choices":[{"label":"a","text":"224 rad"},{"label":"b","text":"183 rad"},{"label":"c","text":"1.83 × 10 –4 rad"},{"label":"d","text":"2.24 × 10 –4 rad"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec02.q014","sourceId":"fs-id1167065913415","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A 500-nm beam of light passing through a diffraction grating creates its second band of constructive interference at an angle of 1.50°. How far apart are the slits in the grating?","images":[],"choices":[{"label":"a","text":"38,200 nm"},{"label":"b","text":"19,100 nm"},{"label":"c","text":"667 nm"},{"label":"d","text":"333 nm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec02.q015","sourceId":"fs-id1167064973745","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"The range of the visible-light spectrum is 380 nm to 780 nm. What is the maximum number of lines per centimeter\na diffraction grating can have and produce a complete first-order spectrum for visible light?","images":[],"choices":[{"label":"a","text":"26,300 lines/cm"},{"label":"b","text":"13,200 lines/cm"},{"label":"c","text":"6,410 lines/cm"},{"label":"d","text":"12,820 lines/cm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec02.q016","sourceId":"fs-id1167062877284","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Two images are just resolved when the center of the diffraction pattern of one is directly over ________ of the diffraction pattern of the other.","images":[],"choices":[{"label":"a","text":"the center"},{"label":"b","text":"the first minimum"},{"label":"c","text":"the first maximum"},{"label":"d","text":"the last maximum"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec02.q018","sourceId":"eip-id1166851051700","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Will a beam of light shining through a 1-mm hole behave any differently than a beam of light that is 1 mm wide as it leaves its source? Explain.?","images":[],"choices":[{"label":"a","text":"Yes, the beam passing through the hole will spread out as it travels, because it is diffracted by the edges of the hole, whereas the 1 -mm beam, which encounters no diffracting obstacle, will not spread out."},{"label":"b","text":"Yes, the beam passing through the hole will be made more parallel by passing through the hole, and so will not spread out as it travels, whereas the unaltered wavefronts of the 1-mm beam will cause the beam to spread out as it travels."},{"label":"c","text":"No, both beams will remain the same width as they travel, and they will not spread out."},{"label":"d","text":"No, both beams will spread out as they travel."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec02.q021","sourceId":"fs-id1167065891150","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Suppose pure-wavelength light falls on a diffraction grating. What happens to the interference pattern if the same light falls on a grating that has more lines per centimeter?","images":[],"choices":[{"label":"a","text":"The bands will spread farther from the central maximum."},{"label":"b","text":"The bands will come closer to the central maximum."},{"label":"c","text":"The bands will not spread farther from the first maximum."},{"label":"d","text":"The bands will come closer to the first maximum."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec02.q022","sourceId":"fs-id1167064872505","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"How many lines per centimeter are there on a diffraction grating that gives a first-order maximum for 473 nm blue\nlight at an angle of 25.0°?","images":[],"choices":[{"label":"a","text":"529,000 lines/cm"},{"label":"b","text":"50,000 lines/cm"},{"label":"c","text":"851 lines/cm"},{"label":"d","text":"8,934 lines/cm"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch17.sec02.q023","sourceId":"fs-id1167064706015","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What is the distance between lines on a diffraction grating that produces a second-order maximum for 760-nm red\nlight at an angle of 60.0°?","images":[],"choices":[{"label":"a","text":"2.28 × 10 4 nm"},{"label":"b","text":"3.29 × 10 2 nm"},{"label":"c","text":"2.53 × 10 1 nm"},{"label":"d","text":"1.76 × 10 3 nm"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":3,"subsectionCount":3,"workedExampleCount":3,"snapLabCount":2,"glossaryCount":7,"assessmentCount":15}}],"summary":{"totalSections":3,"totalKeyEquations":3,"totalWorkedExamples":5,"totalSnapLabs":2,"totalGlossaryTerms":11,"totalAssessments":26,"referencedMediaCount":20},"qualityGate":{"passed":true,"checkedUids":42,"errors":[],"warnings":[]}};
